{
  "source": "The Great Wave off Kanagawa (Ukiyo-e Thirty-Six Views of Mount Fuji, Third Plate: Kanagawa, Wave No. 1), Katsushika Hokusai, c. 1831, public domain",
  "image": "./print.jpg",
  "taken_from_print": {
    "composition": [
      "Dominant breaking wave occupying the left half, crest curling over toward center",
      "Smaller foam-topped swells across the foreground",
      "Small snow-capped Mount Fuji low on the horizon, slightly right of center, framed between the waves",
      "Cream washi-colored sky with flat cloud bands upper right",
      "Three fishing boats (sampans) caught in the troughs between the swells: one large at bottom center, one tilted nose-down at mid-right, one smaller tucked under the great wave at mid-left"
    ],
    "palette": {
      "paper_sky": "#E9D8A6",
      "wave_blue_deep": "#123A5C",
      "wave_blue": "#24567E",
      "trough_blue": "#3D739B",
      "foam_white": "#F4F1E4",
      "hull_wood": "#C98A4B",
      "roof_dark_wood": "#6E4A26",
      "fuji_snow": "#F7F5EC",
      "fuji_rock": "#3A5A77"
    },
    "boats": 3,
    "mountain": "Mount Fuji"
  },
  "scene": "./scene/index.html",
  "assumptions": [
    "No camera controls: it is a wallpaper, viewed head-on with a slow drift",
    "Motion is gentle: boats bob and tilt, clouds and the great wave breathe slightly, camera drifts a few units",
    "No textures: the print is recreated with flat-shaded low-poly geometry only",
    "External resources limited to Google Fonts (Noto Serif JP for the caption) and the three.js module from cdn.jsdelivr.net"
  ]
}


